use crate::expr::Expr;
use crate::logical::{AggregateExpr, JoinType, SetOpType};
use dtdb_relational::{Row, Schema};
use dtdb_storage::DbValue;
use std::collections::HashMap;

/// PhysicalOperator defines the Volcano Iterator interface for query execution.
pub trait PhysicalOperator {
    /// Returns the next row in the stream, or `None` if the stream is exhausted.
    fn next(&mut self) -> Result<Option<Row>, String>;

    /// Returns the output Schema generated by this operator.
    fn schema(&self) -> &Schema;

    /// Formats the operator tree recursively for explanation.
    fn explain(&self, indent: usize, out: &mut String);
}

// ==========================================
// 1. SeqScan Physical Operator
// ==========================================
pub struct PhysicalSeqScan {
    schema: Schema,
    rows_iter: std::vec::IntoIter<Row>,
}

impl PhysicalSeqScan {
    pub fn new(schema: Schema, rows: Vec<Row>) -> Self {
        Self {
            schema,
            rows_iter: rows.into_iter(),
        }
    }
}

impl PhysicalOperator for PhysicalSeqScan {
    fn next(&mut self) -> Result<Option<Row>, String> {
        Ok(self.rows_iter.next())
    }

    fn schema(&self) -> &Schema {
        &self.schema
    }

    fn explain(&self, indent: usize, out: &mut String) {
        out.push_str(&format!(
            "{}- PhysicalSeqScan: schema={:?}\n",
            "  ".repeat(indent),
            self.schema
        ));
    }
}

